items.prompt:
请为这组{{图片类型}}制定商业修图方案。
用途：{{投放渠道}}
目标风格：{{目标风格}}
必须保留：{{保留内容}}
允许修改：{{修改范围}}
交付规格：{{交付规格}}
请输出逐图问题诊断、局部调整步骤、可用于图像编辑工具的提示词和验收清单。不要凭空改变商品细节或人物身份；没有实际编辑工具时只提供方案并明确说明。

commands:
belt app run openai/gpt-image-2-5-flare --input '{
  "prompt": "professional product photo of sneakers, studio lighting",
  "quality": "high"
}'

belt app run openai/gpt-image-2-5-sunburst --input '{
  "prompt": "change the background to a beach at sunset",
  "images": ["https://your-image.jpg"]
}'

belt app run falai/flux-dev-lora --input '{
  "prompt": "professional product photo of a coffee mug, studio lighting"
}'

belt app run google/veo-3-1-fast --input '{
  "prompt": "A timelapse of a flower blooming in a garden"
}'

belt app run xai/grok-imagine-video --input '{
  "prompt": "Waves crashing on a beach at sunset",
  "duration": 5
}'

belt app run falai/wan-2-5-i2v --input '{
  "image": "https://your-image.jpg",
  "prompt": "slow camera push-in"
}'

belt app run bytedance/omnihuman-1-5 --input '{
  "image": "https://portrait.jpg",
  "audio": "https://speech.mp3"
}'

belt login

# Generate a still image
belt app run falai/flux-dev-lora --input '{
  "prompt": "serene mountain lake at sunset, snow-capped peaks reflected in still water, golden hour light, landscape photography",
  "width": 1248,
  "height": 832
}'

# Animate it
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "gentle ripples on the lake surface, clouds slowly drifting, warm light shifting, birds flying in the distance",
  "image": "path/to/lake-image.png"
}'

# Landscape animation
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "gentle camera pan right, water reflecting moving clouds, trees swaying slightly in breeze, warm golden light, peaceful and slow",
  "image": "landscape.png"
}'

# Portrait animation
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "subtle breathing motion, slight head turn, natural eye blink, hair moving gently, soft ambient lighting shifts",
  "image": "portrait.png"
}'

# Product shot animation
belt app run bytedance/seedance-2-0 --input '{
  "prompt": "slow 360 degree orbit around the product, gentle spotlight movement, subtle reflections shifting, premium product showcase, smooth motion",
  "image": "product.png",
  "generate_audio": true
}'

# Fabric/cloth animation
belt app run falai/fabric-1-0 --input '{
  "prompt": "fabric flowing and rippling in gentle wind, natural cloth physics, soft movement",
  "image": "fabric-scene.png"
}'

# Architectural visualization
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "slow dolly forward through the entrance, slight camera tilt upward, ambient light filtering through windows, dust particles in light beams",
  "image": "building-interior.png"
}'

# Generate 3 clips from the same image with progressive motion
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "slow pan left, gentle water motion",
  "image": "scene.png"
}' --no-wait

belt app run falai/wan-2-5-i2v --input '{
  "prompt": "continuing pan, clouds shifting, light changing",
  "image": "scene.png"
}' --no-wait

# Stitch together
belt app run infsh/media-merger --input '{
  "media_files": [
    {"file": "clip1.mp4", "transition_type": "crossfade"},
    {"file": "clip2.mp4"}
  ]
}'

# 1. Generate source image (best quality)
belt app run bytedance/seedream-4-5 --input '{
  "prompt": "cinematic landscape, misty mountains at dawn, lake in foreground, dramatic clouds, golden hour, 4K quality, professional photography",
  "size": "2K"
}'

# 2. Animate the image
belt app run falai/wan-2-5-i2v --input '{
  "prompt": "gentle mist rolling through the valley, lake surface rippling, clouds slowly moving, birds in distance, warm light shifting",
  "image": "landscape.png"
}'

# 3. Upscale video if needed
belt app run falai/topaz-video-upscaler --input '{
  "video": "animated-landscape.mp4"
}'

# 4. Add ambient audio
belt app run infsh/mmaudio --input '{
  "video_input": "animated-landscape.mp4",
  "prompt": "gentle nature ambience, distant birds, soft wind, water lapping"
}'

# 5. Merge video with audio
belt app run infsh/video-audio-merger --input '{
  "video_file": "upscaled-landscape.mp4",
  "audio_file": "ambient-audio.flac"
}'

belt app run falai/wan-2-5-i2v --input '{
  "prompt": "only the waterfall is moving, everything else remains perfectly still, water cascading smoothly, rest of scene frozen",
  "image": "waterfall-scene.png"
}'

belt app run falai/reve --input '{
  "prompt": "remove the background, make it transparent",
  "image": "https://portrait.jpg"
}'

belt app run falai/reve --input '{
  "prompt": "change the background to a beach",
  "image": "https://product-photo.jpg"
}'

# 1. Generate script with Claude
belt app run openrouter/claude-sonnet-45 --input '{
  "prompt": "Write a 30-second script about the future of AI. Make it engaging and conversational. Just the script, no stage directions."
}' > script.json

# 2. Generate voiceover with Kokoro
belt app run falai/kokoro-tts --input '{
  "prompt": "<script-text>",
  "voice": "af_sarah"
}' > voice.json

# 3. Generate background image with FLUX
belt app run falai/flux-dev --input '{
  "prompt": "Futuristic city skyline at sunset, cyberpunk aesthetic, 4K wallpaper"
}' > background.json

# 4. Animate image to video with Wan
belt app run falai/wan-2-5-i2v --input '{
  "image": "<background-url>",
  "prompt": "slow camera pan across cityscape, subtle movement"
}' > video.json

# 5. Add captions (manually or with another tool)

# 6. Merge video with audio
belt app run infsh/video-audio-merger --input '{
  "video_file": "<video-url>",
  "audio_file": "<voice-url>"
}'

# 1. Write the script
belt app run openrouter/claude-sonnet-45 --input '{
  "prompt": "Write a 1-minute explainer script about quantum computing for beginners."
}' > script.json

# 2. Generate speech
belt app run falai/kokoro-tts --input '{
  "prompt": "<script>",
  "voice": "am_michael"
}' > speech.json

# 3. Generate or use a portrait image
belt app run falai/flux-dev --input '{
  "prompt": "Professional headshot of a friendly tech presenter, neutral background, looking at camera"
}' > portrait.json

# 4. Create talking head video
belt app run bytedance/omnihuman-1-5 --input '{
  "image": "<portrait-url>",
  "audio": "<speech-url>"
}' > talking_head.json

# 1. Generate product image
belt app run falai/flux-dev --input '{
  "prompt": "Sleek wireless earbuds on white surface, studio lighting, product photography"
}' > product.json

# 2. Animate product reveal
belt app run falai/wan-2-5-i2v --input '{
  "image": "<product-url>",
  "prompt": "slow 360 rotation, smooth motion"
}' > product_video.json

# 3. Upscale video quality
belt app run falai/topaz-video-upscaler --input '{
  "video": "<product-video-url>"
}' > upscaled.json

# 4. Add background music
belt app run infsh/video-audio-merger --input '{
  "video_file": "<upscaled-url>",
  "audio_file": "https://your-music.mp3"
}'

# 1. Summarize blog post
belt app run openrouter/claude-haiku-45 --input '{
  "prompt": "Summarize this blog post into 5 key points for a video script: <blog-content>"
}' > summary.json

# 2. Generate images for each point
for i in 1 2 3 4 5; do
  belt app run falai/flux-dev --input "{
    \"prompt\": \"Visual representing point $i: <point-text>\"
  }" > "image_$i.json"
done

# 3. Animate each image
for i in 1 2 3 4 5; do
  belt app run falai/wan-2-5-i2v --input "{
    \"image\": \"<image-$i-url>\",
    \"prompt\": \"subtle camera motion\"
  }" > "video_$i.json"
done

# 4. Generate voiceover
belt app run falai/kokoro-tts --input '{
  "prompt": "<full-script>",
  "voice": "bf_emma",
  "language": "british-english"
}' > narration.json

# 5. Merge all clips
belt app run infsh/media-merger --input '{
  "media_files": [
    {"file": "<video1>", "transition_type": "crossfade"},
    {"file": "<video2>", "transition_type": "crossfade"},
    {"file": "<video3>", "transition_type": "crossfade"},
    {"file": "<video4>", "transition_type": "crossfade"},
    {"file": "<video5>", "transition_type": "crossfade"}
  ]
}' > merged.json

belt app run infsh/video-audio-merger --input '{
  "video_file": "<merged-url>",
  "audio_file": "<narration-url>"
}'

